INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(16783, 'plPL', 'Rób, co mówię! Leć!', 'Rób, co mówię! Leć!', 0),
(16784, 'plPL', 'Chronić Botanikę za wszelką cenę!', '', 0),
(16785, 'plPL', 'Wszyscy intruzi muszą zostać wyeliminowani!', '', 0),
(16942, 'plPL', 'Najwyższy Botaniku?', 'Najwyższy Botaniku?', 0),
(16945, 'plPL', '...mamrocze...Płatki ognia...mamrocze...', '', 0),
(16946, 'plPL', '...mamrocze, mamrocze...', '', 0),
(16947, 'plPL', '...ciernie pnącza...mamrocze...au!', '', 0),
(16948, 'plPL', '...przy odpowiedniej mieszance, może...', '', 0),
(16961, 'plPL', 'Witajcie, bracia! Napawajcie się chwałą mojej mocy!', '', 0),
(16993, 'plPL', 'Uciekajcie stąd, jest ich za dużo! Uciekajcie, póki możecie!', 'Uciekajcie stąd, jest ich za dużo! Uciekajcie, póki możecie!', 0),
(16994, 'plPL', 'Pomocy! Niech ktoś nam pomoże!', 'Pomocy! Niech ktoś nam pomoże!', 0),
(16999, 'plPL', '', 'Tak. To zadziałało.', 0),
(17000, 'plPL', '', 'Hmm...', 0),
(17178, 'plPL', 'Hmm... Obrona przed mrozem, ogniem i tajemną mocą reaguje szybciej niż w partii 7, ale obrona przed naturą pozostaje bierna.', 'Hmm... Obrona przed mrozem, ogniem i tajemną mocą reaguje szybciej niż w partii 7, ale obrona przed naturą pozostaje bierna.', 0),
(17562, 'plPL', '', '%s wzywa posiłki!', 0),
(17624, 'plPL', 'Zabić $n!', 'Zabić $n!', 0),
(18376, 'plPL', 'Dzieci, do mnie!', 'Dzieci, do mnie!', 0),
(19936, 'plPL', '', 'Podejdźcie. Dopilnuję, by was należycie powitano!', 0),
(19937, 'plPL', '', 'Och, przestań skomleć!', 0),
(19938, 'plPL', '', 'Misja wykonana!', 0),
(19939, 'plPL', '', 'Nie masz już do czynienia z byle podwładnym!', 0),
(19940, 'plPL', '', 'Band\'or shorel\'aran!', 0),
(19941, 'plPL', '', 'Straże, do mnie! Wyrżnąć tych najeźdźców!', 0),
(19942, 'plPL', '', 'Jeszcze nawet... nie zaczęłam...', 0),
(19944, 'plPL', 'Co wy wyprawiacie? Te okazy są bardzo delikatne!', '', 0),
(19945, 'plPL', 'Twój cykl życiowy właśnie się zakończył.', '', 0),
(19946, 'plPL', 'Nakarmisz robaki.', '', 0),
(19947, 'plPL', 'Endorel anuminor!', '', 0),
(19948, 'plPL', 'Natura ugina się przed moją wolą...', '', 0),
(19949, 'plPL', 'Okazy... trzeba ocalić.', '', 0),
(20012, 'plPL', 'Co to za utrapienie? Zginiecie!', '', 0),
(20013, 'plPL', 'Szukacie nagrody, co? A może być śmierć?', '', 0),
(20014, 'plPL', 'Nie lubię mówić „a nie mówiłem”...', '', 0),
(20015, 'plPL', 'Twoje życie będzie moje!', '', 0),
(20016, 'plPL', 'Rozkoszuję się waszym bólem!', '', 0),
(20017, 'plPL', 'Spopielę was!', '', 0),
(20018, 'plPL', 'Krzyczcie, płonąc!', '', 0),
(20019, 'plPL', 'Daleko... nie zajdziecie.', '', 0),
(20022, 'plPL', 'Może to nie jest... Nie, walczymy! Pomóżcie mi!', 'Może to nie jest... Nie, walczymy! Pomóżcie mi!', 0),
(20024, 'plPL', 'Kto zakłóca spokój tego sanktuarium?', 'Kto zakłóca spokój tego sanktuarium?', 0),
(20025, 'plPL', 'Musicie zginąć! Ale chwila: to nie... Nie, nie... musicie zginąć!', 'Musicie zginąć! Ale chwila: to nie... Nie, nie... musicie zginąć!', 0),
(20026, 'plPL', 'Co ja robię? Dlaczego ja...', 'Co ja robię? Dlaczego ja...', 0),
(20028, 'plPL', 'Tak... zagubiony. Nie... należę tutaj.', 'Tak... zagubiony. Nie... należę tutaj.', 0);
